from test_helpers import test,solo

test('Thanks tolerates unrelated secret timing',solo+"auras.player={{spellId=999999,name='Other',duration={secret=true},expirationTime=0}}; BuffTap:InvalidateAura('player'); BuffTap:ObserveSoloThanks(); received(1459,'target'); assert(#emotes==1)")
test('Thanks accepts recognized buff with hidden timing',solo+"auras.player={{spellId=1459,name='Arcane Intellect',sourceUnit='target',duration={secret=true},expirationTime={secret=true}}}; BuffTap:InvalidateAura('player'); BuffTap:ObserveSoloThanks(); assert(#emotes==1)")
test('Thanks preserves baseline through total read failure',solo+"local old=C_UnitAuras.GetAuraDataByIndex; C_UnitAuras.GetAuraDataByIndex=function() error('blocked') end; BuffTap:InvalidateAura('player'); BuffTap:ObserveSoloThanks(); assert(BuffTap.helperThankSeen); C_UnitAuras.GetAuraDataByIndex=old; received(1459,'target'); assert(#emotes==1)")
test('Thanks tracks replacement instances of the same spell',solo+"received(1459,'target'); now=now+61; auras.player={{spellId=1459,name='Arcane Intellect',duration=600,expirationTime=now+600,sourceUnit='party1',auraInstanceID=55}}; BuffTap:InvalidateAura('player'); BuffTap:ObserveSoloThanks(); assert(#emotes==2)")
test('Thanks recognizes fresh same-instance expiration after provider cooldown',solo+"received(1459,'target'); now=now+61; auras.player[1].expirationTime=now+600; BuffTap:InvalidateAura('player'); BuffTap:ObserveSoloThanks(); assert(#emotes==2)")
test('Unchanged repeated aura events do not repeat thanks',solo+"received(1459,'target'); now=now+61; for n=1,5 do BuffTap:InvalidateAura('player'); BuffTap:ObserveSoloThanks() end; assert(#emotes==1)")
test('Cold thanks baseline settles without thanking existing buffs',solo+"BuffTap.helperThankSeen=nil; received(1459,'target'); advance(.3); assert(#emotes==0 and BuffTap.helperThankSeen); received(1243,'target'); assert(#emotes==1)")
test('Distinct providers in one scan each receive queued thanks',solo+"auras.player={{spellId=1459,name='Intellect',duration=600,expirationTime=now+600,sourceUnit='target',auraInstanceID=1},{spellId=1243,name='Fortitude',duration=600,expirationTime=now+600,sourceUnit='party1',auraInstanceID=2}}; BuffTap:InvalidateAura('player'); BuffTap:ObserveSoloThanks(); assert(#emotes==1); advance(1.1); assert(#emotes==2)")
test('Different provider buff is queued rather than lost during one-second gap',solo+"received(1459,'target'); received(1243,'party1'); assert(#emotes==1); advance(.5); assert(#emotes==1); advance(.6); assert(#emotes==2)")
test('Multiple quick buffs from one source produce one emote',solo+"received(1459,'target'); received(1243,'target'); received(14752,'target'); advance(2); assert(#emotes==1)")
test('Per-source cooldown blocks before minute and permits after minute',solo+"received(1459,'target'); now=now+59; received(1243,'target'); assert(#emotes==1); now=now+2; received(14752,'target'); assert(#emotes==2)")
test('Queued caster identity change cannot thank reused token',solo+"received(1459,'target'); received(1243,'party1'); local old=UnitGUID; UnitGUID=function(u) return u=='party1' and 'Replacement' or old(u) end; advance(1.1); assert(#emotes==1)")
test('Queued thanks is discarded on combat',solo+"received(1459,'target'); received(1243,'party1'); combat=true; BuffTap:HelperEvent('PLAYER_REGEN_DISABLED'); advance(1.1); assert(#emotes==1 and #BuffTap.helperThankQueue==0)")
test('Queued thanks is discarded on entering group',solo+"received(1459,'target'); received(1243,'party1'); IsInGroup=function() return true end; BuffTap:HelperEvent('GROUP_ROSTER_UPDATE'); advance(1.1); assert(#emotes==1)")
test('Disabled thanks cannot dispatch queued message',solo+"received(1459,'target'); received(1243,'party1'); BuffTap.db.helperThanks=false; advance(1.1); assert(#emotes==1)")
test('Known aura identity can settle briefly delayed caster',solo+"auras.player={{spellId=1459,name='Intellect',duration=600,expirationTime=now+600,auraInstanceID=42}}; BuffTap:InvalidateAura('player'); BuffTap:ObserveSoloThanks(); assert(#emotes==0); auras.player[1].sourceUnit='target'; advance(.3); assert(#emotes==1)")
test('Secret caster stays silent and retries are bounded',solo+"auras.player={{spellId=1459,name='Intellect',duration=600,expirationTime=now+600,sourceUnit={secret=true},auraInstanceID=42}}; BuffTap:InvalidateAura('player'); BuffTap:ObserveSoloThanks(); for n=1,15 do advance(.21) end; assert(#emotes==0 and not BuffTap.helperThankRetryPending)")
test('Diagnostics includes thanks observation state',solo+"received(1459,'target'); assert(table.concat(BuffTap:DiagnosticsLines(),' '):find('Solo thanks:'))")

test('Late instance metadata does not turn existing buff into a new thanks',solo+"aura('player',1459,'Intellect',600,600); auras.player[1].sourceUnit='target'; BuffTap:ObserveSoloThanks(true); auras.player[1].auraInstanceID=99; BuffTap:InvalidateAura('player'); BuffTap:ObserveSoloThanks(); assert(#emotes==0)")
test('Queue retains original resolved name rather than a later bystander name',solo+"received(1459,'target'); GetUnitName=function(u) return u=='party1' and 'Original-Realm' or 'Other' end; received(1243,'party1'); GetUnitName=function() return 'Changed' end; advance(1.1); assert(emotes[2][2]=='Original-Realm')")
test('Profile changes discard queued thanks and preserve source cooldown',solo+"received(1459,'target'); received(1243,'party1'); assert(#emotes==1); local last=BuffTap.helperLastThank; assert(BuffTap:CreateSettingsProfile('Thanks copy',true)); advance(2); assert(#emotes==1 and BuffTap.helperLastThank==last and #BuffTap.helperThankQueue==0)")
